import subprocess, re

def pages(pdf):
    t=subprocess.run(['pdftotext','-layout',pdf,'-'],capture_output=True,text=True).stdout
    return t.split('\f')

def norm(s):
    return re.sub(r'[^a-z0-9]+',' ',s.lower()).strip()

def contents_pageno(pgs, heading):
    """Find the Contents line for `heading` and return the page number it claims."""
    h=norm(heading)
    for p in pgs:
        for line in p.splitlines():
            # a contents line: contains the heading and ends with a page number, with leader dots/spaces between
            m=re.match(r'^\s*(.*?)[\s.·…_]{2,}(\d{1,4})\s*$', line)
            if m and norm(m.group(1)).endswith(h) or (m and h in norm(m.group(1)) and norm(m.group(1)).replace(h,'').strip()==''):
                return int(m.group(2)), line.strip()
    return None, None

def heading_pages(pgs, heading, printed_offset=0):
    """Pages (1-based physical) where `heading` appears as a HEADING-shaped line:
       a short standalone line equal to the heading (modulo a leading section number),
       NOT a contents line and NOT buried in prose."""
    h=norm(heading)
    hits=[]
    for i,p in enumerate(pgs, start=1):
        for line in p.splitlines():
            if re.search(r'[.·…_]{3,}\s*\d{1,4}\s*$', line):   # skip contents lines
                continue
            nl=norm(line)
            # strip a leading section number like "3.4" or "F.4.2"
            nl_ns=re.sub(r'^[a-z]?\s*\d+(?:\s+\d+)*\s+','',nl)
            core=nl_ns if nl_ns else nl
            if (core==h or nl==h) and len(line.strip())<=max(40,len(heading)+12):
                hits.append(i)
                break
    return hits

vols={
 'math.pdf':    [('all','Math'),('Q.exch','Math')],
 'physics.pdf': [('Failure modes','Physics')],
 'spectra.pdf': [('The isoelectronic ladder','Spectra'),('The staged cells','Spectra')],
}
for pdf,cands in vols.items():
    pgs=pages('OUT/'+pdf)
    npg=len([x for x in pgs])
    print(f"===== {pdf}  ({npg} pages) =====")
    for heading,_ in cands:
        claimed,cline=contents_pageno(pgs,heading)
        actual=heading_pages(pgs,heading)
        verdict='?'
        if claimed is None:
            verdict='NO CONTENTS LINE FOUND (heading may be phrased differently in TOC)'
        elif not actual:
            verdict='heading not found as a heading-shaped line (needs manual look)'
        elif claimed in actual:
            verdict=f'OK — Contents page {claimed} hosts the heading (was a checker artifact)'
        else:
            verdict=f'MIS-PAGE — Contents says {claimed}, heading is on {actual}'
        print(f"  '{heading}': claimed={claimed} actual={actual} -> {verdict}")
PYEOF

